import React, { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { Mail, Webhook, Plus } from 'lucide-react';
import { Input } from './ui/Input';
import { Button } from './ui/Button';
import { Card } from './ui/Card';
import type { CreateAlertChannelInput } from '@pingwatch/shared';

const channelSchema = z.object({
  channel_type: z.enum(['email', 'webhook']),
  email: z.string().email('Invalid email address').optional().or(z.literal('')),
  url: z.string().url('Invalid URL').startsWith('https://', 'URL must start with https://').optional().or(z.literal('')),
}).refine(
  (data) => {
    if (data.channel_type === 'email') return !!data.email && data.email.length > 0;
    if (data.channel_type === 'webhook') return !!data.url && data.url.length > 0;
    return false;
  },
  {
    message: 'Please fill in the required destination for the selected channel type',
    path: ['email'],
  }
);

type FormValues = z.infer<typeof channelSchema>;

interface AlertChannelFormProps {
  siteId?: string | null;
  onAddChannel: (input: CreateAlertChannelInput) => Promise<any>;
}

export function AlertChannelForm({ siteId = null, onAddChannel }: AlertChannelFormProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const {
    register,
    handleSubmit,
    watch,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<FormValues>({
    resolver: zodResolver(channelSchema),
    defaultValues: {
      channel_type: 'email',
      email: '',
      url: '',
    },
  });

  const selectedType = watch('channel_type');

  const onSubmit = async (values: FormValues) => {
    try {
      setErrorMsg(null);
      await onAddChannel({
        site_id: siteId || null,
        channel_type: values.channel_type,
        config:
          values.channel_type === 'email'
            ? { email: values.email }
            : { url: values.url },
      });

      reset();
      setIsOpen(false);
    } catch (err: any) {
      setErrorMsg(err.message || 'Failed to add alert channel');
    }
  };

  if (!isOpen) {
    return (
      <Button
        type="button"
        variant="secondary"
        size="sm"
        onClick={() => setIsOpen(true)}
        className="gap-1.5"
      >
        <Plus className="h-3.5 w-3.5" /> Add Alert Channel
      </Button>
    );
  }

  return (
    <Card className="border-[#30363D] bg-[#161B22]/90 mt-3 p-4">
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <div className="flex items-center justify-between border-b border-[#30363D] pb-2">
          <h4 className="text-xs font-semibold uppercase tracking-wider text-[#8B949E]">
            {siteId ? 'Add Site Alert Channel' : 'Add Global Alert Channel'}
          </h4>
          <button
            type="button"
            onClick={() => setIsOpen(false)}
            className="text-xs text-[#8B949E] hover:text-white"
          >
            Cancel
          </button>
        </div>

        {errorMsg && (
          <p className="text-xs text-[#FF4D4F]">{errorMsg}</p>
        )}

        <div className="flex gap-4">
          <label className="flex items-center gap-2 text-xs text-white cursor-pointer">
            <input
              type="radio"
              value="email"
              {...register('channel_type')}
              className="accent-[#00FF87]"
            />
            <Mail className="h-3.5 w-3.5 text-[#00FF87]" /> Email Alert
          </label>
          <label className="flex items-center gap-2 text-xs text-white cursor-pointer">
            <input
              type="radio"
              value="webhook"
              {...register('channel_type')}
              className="accent-[#00FF87]"
            />
            <Webhook className="h-3.5 w-3.5 text-[#58A6FF]" /> HTTPS Webhook
          </label>
        </div>

        {selectedType === 'email' ? (
          <div>
            <Input
              type="email"
              label="Recipient Email"
              placeholder="alerts@yourcompany.com"
              error={errors.email?.message}
              {...register('email')}
            />
          </div>
        ) : (
          <div>
            <Input
              type="url"
              label="Webhook URL"
              placeholder="https://hooks.slack.com/services/..."
              error={errors.url?.message}
              {...register('url')}
            />
          </div>
        )}

        <div className="flex justify-end gap-2 pt-1">
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => setIsOpen(false)}
          >
            Cancel
          </Button>
          <Button type="submit" variant="primary" size="sm" isLoading={isSubmitting}>
            Save Channel
          </Button>
        </div>
      </form>
    </Card>
  );
}
